    section8Body: 'হরমোনের ওঠানামা মেজাজের পরিবর্তনের সঙ্গে একই সময়ে ঘটতে পারে, তবে এটিই একমাত্র ব্যাখ্যা নয়: ঘুম, মানসিক চাপ, জীবনের পরিবর্তন এবং শারীরিক উপসর্গও ভূমিকা রাখে।',
