    section4Body: 'Progesteron faqat ovulyatsiyadan keyin ishlab chiqariladi. Biroq perimenopauza davomida ovulyatsiyaning oʻzi notekisroq boʻladi — bu uning ishlab chiqarilishini kamroq oldindan aytib boʻladigan qiladi.',
    section4Body2: 'Bu notekislik sikldagi kuzatiladigan oʻzgarishlarni qisman tushuntiradi: oʻzgaruvchan uzunlik, avvalgidan baʼzan koʻproq yoki kamroq hayzlar.',
    section5Body: 'Gormonal tebranishlardan tashqari, boshqa bir qancha omillar ham taʼsir qiladi: uyqu sifati, stress darajasi, turmush tarzi va har bir odamga xos farqlar.',
