    section6Caption: 'Bu roʻyxat faqat maʼlumot uchun: u tashxis emas. Har kim bu oʻzgarishlarning turli kombinatsiyasini boshdan kechiradi.',
    section7Body: 'Tungi terlash uyquni uzishi, ertasi kuni charchoq va diqqatni jamlashda qiyinchilikka olib kelishi mumkin — bu shu davrda keng tarqalgan holat.',
    infoCard2Title: 'Amaliy maslahat',
    infoCard2Text: 'Salqin yotoqxona, yengil kiyim va barqaror uxlash tartibi bu uygʻonishlarni cheklashga yordam beradi.',
    section8Body: 'Gormonal tebranishlar kayfiyat oʻzgarishlariga toʻgʻri kelishi mumkin, ammo yagona izoh emas: uyqu, stress, hayotdagi oʻzgarishlar va jismoniy alomatlar ham rol oʻynaydi.',
    infoCard3Title: 'Sizni tinchlantirish uchun',
    infoCard3Text: 'Bu davrda hissiyotliroq boʻlish nimadir notoʻgʻriligini anglatmaydi: bu bir vaqtning oʻzida bir nechta sababi boʻlishi mumkin boʻlgan keng tarqalgan tajriba.',
    section9Body: 'Perimenopauza davomida gormon darajasi kundan kunga sezilarli farq qilishi mumkin. Shuning uchun yakka tahlil vaziyatning toʻliq tasvirini har doim ham bermaydi.',
    infoCard4Title: 'Esda tutishga arziydi',
    infoCard4Text: 'Tibbiy baholash asosan yoshingizga, alomatlaringizga va sikl tarixingizga bogʻliq — faqat bitta raqamga emas.',
    section10Body: 'Oyma-oy boshdan kechirgan narsangizni yozib borish boshqalar bilan solishtirish oʻrniga oʻz qonuniyatlaringizni payqashga yordam beradi:',
