    section6Caption: 'ეს სია მხოლოდ საინფორმაციოა: ის დიაგნოზი არ არის. თითოეული ადამიანი ამ ცვლილებების განსხვავებულ კომბინაციას განიცდის.',
    section7Body: 'ღამის ოფლიანობამ შეიძლება ძილი შეწყვიტოს, რამაც მეორე დღეს დაღლილობა და კონცენტრაციის სირთულე გამოიწვიოს — ეს ამ პერიოდში გავრცელებული სურათია.',
