    section8Body: 'ჰორმონული ცვალებადობა შეიძლება ხასიათის ცვლილებებს ემთხვეოდეს, თუმცა ერთადერთი ახსნა არ არის: ძილი, სტრესი, ცხოვრებისეული ცვლილებები და ფიზიკური სიმპტომებიც მნიშვნელოვან როლს თამაშობს.',
