    section6Caption: 'Այս ցանկը միայն տեղեկատվական նպատակով է. այն ախտորոշում չէ: Յուրաքանչյուր մարդ ապրում է այս փոփոխությունների տարբեր համադրություն:',
    section7Body: 'Գիշերային քրտնարտադրությունը կարող է ընդհատել քունը՝ հանգեցնելով հոգնածության և կենտրոնանալու դժվարության հաջորդ օրը. օրինաչափություն, որը տարածված է այս շրջանում:',
    infoCard2Title: 'Գործնական խորհուրդ',
    infoCard2Text: 'Զով ննջարանը, թեթև հագուստը և կայուն քնելու ռեժիմը կարող են օգնել սահմանափակել այս արթնացումները:',
    section8Body: 'Հորմոնալ տատանումները կարող են համընկնել տրամադրության փոփոխությունների հետ՝ առանց միակ բացատրությունը լինելու. քունը, սթրեսը, կյանքի փոփոխությունները և ֆիզիկական ախտանիշները նույնպես դեր են խաղում:',
    infoCard3Title: 'Ձեզ հանգստացնելու համար',
    infoCard3Text: 'Այս շրջանում ավելի հուզական զգալը չի նշանակում, որ ինչ-որ բան այն չէ. դա տարածված փորձառություն է, որը կարող է միաժամանակ ունենալ մի քանի պատճառ:',
    section9Body: 'Պերիմենոպաուզայի ընթացքում հորմոնների մակարդակները կարող են զգալիորեն տարբերվել մի օրից մյուսը: Ուստի մեկ անալիզը միշտ չէ, որ տալիս է իրավիճակի ամբողջական պատկերը:',
    infoCard4Title: 'Արժե հիշել',
    infoCard4Text: 'Բժշկական գնահատումը հիմնականում կախված է ձեր տարիքից, ախտանիշներից և ցիկլի պատմությունից, այլ ոչ թե միայն մեկ թվից:',
    section10Body: 'Ամիս առ ամիս ձեր ապրածը գրանցելը օգնում է նկատել ձեր սեփական օրինաչափությունները՝ ուրիշների հետ ինքներդ ձեզ համեմատելու փոխարեն.',
