    section2Body: 'Тухмдонҳо тадриҷан ба сигналҳои гормонии аз майна фиристодашуда камтар мунтазам посух медиҳанд. Ин давраҳоро номунтазам мекунад ва шарҳ медиҳад, ки чаро нишонаҳо метавонанд аз моҳ ба моҳ тағйир ёбанд.',
    tip1Title: 'Донистан хуб аст',
    tip1Text: 'Комилан имконпазир аст, ки як моҳ нишонаҳои намоён дошта бошед ва моҳи дигар қариб ягон нишона набошад. Ин ғайримуқаррарӣ нест: он танҳо тағйироти гормонии ин давраро инъикос мекунад.',
