    section7Body: 'Арақи шабона метавонад хобро қатъ кунад ва ба хастагӣ ва душвории тамаркуз дар рӯзи дигар оварда расонад — намунаи маъмул дар ин давра.',
    infoCard2Title: 'Маслиҳати амалӣ',
